//! ⚖️ Original Layout equality lends original native fields and grows only funded scalar frame storage.
use semio_framework_pack_json::{ArtifactCanonicalJsonTree as Tree,ArtifactCanonicalJsonNode as Node,ArtifactCanonicalJsonText as Text};
use semio_s_artifact_layout_layout_model::snapshot::LayoutSnapshot;
use semio_framework_value::{RetirementDemand,ValueError,ValueRefusalKind,retained_clone::{RetainedCloneBinding,RetainedCloneRef,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,retained_clone_grant_admits}};
use std::mem::{ManuallyDrop,size_of};
#[derive(Clone,Copy)]struct Frame{left:&'static dyn Tree,right:&'static dyn Tree,index:usize,count:usize,phase:u8,object:bool,left_chunk:usize,left_offset:usize,right_chunk:usize,right_offset:usize}
impl Frame{fn new(left:&'static dyn Tree,right:&'static dyn Tree)->Self{Self{left,right,index:0,count:0,phase:0,object:false,left_chunk:0,left_offset:0,right_chunk:0,right_offset:0}}fn reset_text(&mut self){self.left_chunk=0;self.left_offset=0;self.right_chunk=0;self.right_offset=0}}
fn invalid()->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,"Layout document original equality custody is invalid")}
fn text(n:Node<'_>)->Option<Text<'_>>{match n{Node::String(s)=>Some(Text::Contiguous(s)),Node::Text(s)=>Some(s),_=>None}}
fn bytes(frame:&mut Frame,l:Text<'_>,r:Text<'_>)->Result<(Option<bool>,usize),ValueError>{let mut count=0;for _ in 0..128{let a=l.next_byte(&mut frame.left_chunk,&mut frame.left_offset).map_err(|_|invalid())?;let b=r.next_byte(&mut frame.right_chunk,&mut frame.right_offset).map_err(|_|invalid())?;count+=usize::from(a.is_some())+usize::from(b.is_some());match(a,b){(None,None)=>return Ok((Some(true),count)),(Some(a),Some(b))if a==b=>{},_=>return Ok((Some(false),count))}}Ok((None,count))}
/// 🛡️ Original source aliases outlive all descendant loans and every old/new scalar frame backing.
pub struct LayoutDocumentEquality{left:Option<RetainedCloneBinding>,right:Option<RetainedCloneBinding>,frames:ManuallyDrop<Vec<Frame>>,next:ManuallyDrop<Option<Vec<Frame>>>,pending:Option<Frame>,phase:u8,copy:usize,growth:usize,result:Option<bool>,closing:bool}
impl Default for LayoutDocumentEquality{fn default()->Self{Self{left:None,right:None,frames:ManuallyDrop::new(Vec::new()),next:ManuallyDrop::new(None),pending:None,phase:0,copy:0,growth:0,result:None,closing:false}}}
impl LayoutDocumentEquality{
 fn fixed()->RetirementDemand{RetirementDemand{copy_bytes:size_of::<Self>()*2+size_of::<Frame>()*4+1024,depth:1,..Default::default()}}
 fn nested(mut d:RetirementDemand)->RetirementDemand{d.copy_bytes+=Self::fixed().copy_bytes;d.depth+=1;d}
 fn child(g:RetainedCloneGrant)->RetainedCloneGrant{RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes-Self::fixed().copy_bytes,maximum_depth:g.maximum_depth-1,..g}}
 fn paid(mut p:RetainedCloneProgress)->RetainedCloneProgress{p.copied_items=p.copied_items.max(1);p.copied_bytes+=Self::fixed().copy_bytes;p}
 fn error(e:ValueError)->ValueError{let p=Self::paid(e.retained_progress());e.with_retained_progress(p)}
 pub fn result(&self)->Option<bool>{self.result}
 pub fn verify(&self,l:RetainedCloneRef<'_,LayoutSnapshot>,r:RetainedCloneRef<'_,LayoutSnapshot>)->Result<(),ValueError>{l.check_binding(&self.left)?;r.check_binding(&self.right)?;Ok(())}
 pub fn demand(&self,l:RetainedCloneRef<'_,LayoutSnapshot>,r:RetainedCloneRef<'_,LayoutSnapshot>)->Result<RetirementDemand,ValueError>{if self.closing{return Err(invalid())}self.verify(l,r)?;Ok(match self.phase{0=>Self::nested(l.binding_demand(&self.left)?.unwrap_or_default()),1=>Self::nested(r.binding_demand(&self.right)?.unwrap_or_default()),4=>RetirementDemand{capacity_bytes:self.growth.checked_mul(size_of::<Frame>()).ok_or_else(invalid)?,..Self::fixed()},7=>RetirementDemand{release_bytes:self.frames.capacity()*size_of::<Frame>(),..Self::fixed()},3=>RetirementDemand{copy_bytes:Self::fixed().copy_bytes+256,..Self::fixed()},_=>Self::fixed()})}
 pub fn advance(&mut self,l:RetainedCloneRef<'_,LayoutSnapshot>,r:RetainedCloneRef<'_,LayoutSnapshot>,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let d=self.demand(l,r)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}let mut p=RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()};if self.result.is_some(){return Ok(RetainedCloneStep::Complete(p))}match self.phase{
 0=>{p=Self::paid(l.bind(&mut self.left,Self::child(g)).map_err(Self::error)?.unwrap_or_default());self.phase=1},1=>{p=Self::paid(r.bind(&mut self.right,Self::child(g)).map_err(Self::error)?.unwrap_or_default());self.phase=2},
 2=>{let a=l.get()as &dyn Tree as *const dyn Tree;let b=r.get()as &dyn Tree as *const dyn Tree;let(left,right):(&'static dyn Tree,&'static dyn Tree)=unsafe{(&*a,&*b)};self.pending=Some(Frame::new(left,right));self.phase=3},
 3=>{p.copied_bytes=Self::fixed().copy_bytes;if let Some(frame)=self.pending{if self.frames.len()==self.frames.capacity(){self.growth=self.frames.capacity().max(1).checked_mul(if self.frames.capacity()==0{1}else{2}).ok_or_else(invalid)?;self.phase=4}else{self.frames.push(frame);self.pending=None}}else{p.copied_bytes+=self.inspect().map_err(|e|e.with_retained_progress(p))?}},
 4=>{self.phase=254;*self.next=Some(Vec::new());let rows=self.next.as_mut().unwrap();let reserved=rows.try_reserve_exact(self.growth);p.retained_capacity_bytes=rows.capacity()*size_of::<Frame>();if reserved.is_err()||p.retained_capacity_bytes>g.maximum_capacity_bytes{return Err(invalid().with_retained_progress(p))}self.copy=0;self.phase=5},
 5=>if self.copy==self.frames.len(){self.phase=6}else{self.next.as_mut().ok_or_else(invalid)?.push(self.frames[self.copy]);self.copy+=1},
 6=>if self.frames.pop().is_none(){self.phase=7},
 7=>{p.released_bytes=self.frames.capacity()*size_of::<Frame>();*self.frames=Vec::new();*self.frames=self.next.take().ok_or_else(invalid)?;self.phase=3},_=>return Err(invalid())}Ok(if self.result.is_some(){RetainedCloneStep::Complete(p)}else{RetainedCloneStep::Progress(p)})}
 fn inspect(&mut self)->Result<usize,ValueError>{let frame=self.frames.last_mut().ok_or_else(invalid)?;let(left,right,index)=(frame.left,frame.right,frame.index);if frame.phase==5{self.frames.pop();if let Some(parent)=self.frames.last_mut(){parent.index+=1;parent.phase=if parent.index==parent.count{5}else if parent.object{1}else{2}}else{self.result=Some(true)}return Ok(0)}if frame.phase==1{let(equal,count)=bytes(frame,left.canonical_tree_key(index)?,right.canonical_tree_key(index)?)?;if let Some(equal)=equal{frame.reset_text();if equal{frame.phase=2}else{self.result=Some(false)}}return Ok(count)}if frame.phase==2{let left=left.canonical_tree_child(index)?;let right=right.canonical_tree_child(index)?;frame.phase=4;self.pending=Some(Frame::new(left,right));return Ok(0)}let a=left.canonical_tree_node()?;let b=right.canonical_tree_node()?;if frame.phase==3{let(equal,count)=bytes(frame,text(a).ok_or_else(invalid)?,text(b).ok_or_else(invalid)?)?;if let Some(equal)=equal{frame.reset_text();if equal{frame.phase=5}else{self.result=Some(false)}}return Ok(count)}if frame.phase!=0{return Err(invalid())}let same=match(a,b){(Node::Array(a),Node::Array(b))|(Node::Object(a),Node::Object(b))=>{if a!=b{Some(false)}else if a==0{Some(true)}else{frame.count=a;frame.object=matches!(left.canonical_tree_node()?,Node::Object(_));frame.phase=if frame.object{1}else{2};None}},(Node::Null,Node::Null)=>Some(true),(Node::Bool(a),Node::Bool(b))=>Some(a==b),(Node::I64(a),Node::I64(b))|(Node::I64Text(a),Node::I64Text(b))=>Some(a==b),(Node::U64(a),Node::U64(b))|(Node::U64Text(a),Node::U64Text(b))=>Some(a==b),(Node::I128(a),Node::I128(b))=>Some(a==b),(Node::U128(a),Node::U128(b))=>Some(a==b),(Node::F32(a),Node::F32(b))|(Node::F32HexWord(a),Node::F32HexWord(b))=>Some(a.to_bits()==b.to_bits()),(Node::F64(a),Node::F64(b))=>Some(a.to_bits()==b.to_bits()),(a,b)=>if text(a).is_some()&&text(b).is_some(){frame.phase=3;None}else{Some(false)}};if let Some(same)=same{if same{frame.phase=5}else{self.result=Some(false)}}Ok(0)}
 pub fn begin_close(&mut self){self.closing=true}
 pub fn close_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.closing{return Err(invalid())}if self.pending.is_some()||!self.frames.is_empty()||self.next.as_ref().is_some_and(|v|!v.is_empty()){return Ok(Self::fixed())}if self.frames.capacity()>0{return Ok(RetirementDemand{release_bytes:self.frames.capacity()*size_of::<Frame>(),..Self::fixed()})}if let Some(next)=self.next.as_ref(){return Ok(RetirementDemand{release_bytes:next.capacity()*size_of::<Frame>(),..Self::fixed()})}Ok(Self::nested(RetainedCloneBinding::close_demand(if self.right.is_some(){&self.right}else{&self.left},body.min(256))?))}
 pub fn close_step(&mut self,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let d=self.close_demand(g.maximum_copy_bytes)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}let mut p=RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()};if self.pending.is_some(){self.pending=None}else if !self.frames.is_empty(){self.frames.pop();}else if self.next.as_ref().is_some_and(|v|!v.is_empty()){self.next.as_mut().unwrap().pop();}else if self.frames.capacity()>0{p.released_bytes=self.frames.capacity()*size_of::<Frame>();*self.frames=Vec::new()}else if let Some(next)=self.next.take(){p.released_bytes=next.capacity()*size_of::<Frame>();drop(next)}else{p=Self::paid(RetainedCloneBinding::close_one(if self.right.is_some(){&mut self.right}else{&mut self.left},Self::child(g)).map_err(Self::error)?.progress())}Ok(if self.terminal_is_empty(){RetainedCloneStep::Complete(p)}else{RetainedCloneStep::Progress(p)})}
 pub fn terminal_is_empty(&self)->bool{self.left.is_none()&&self.right.is_none()&&self.pending.is_none()&&self.frames.capacity()==0&&self.next.is_none()}
}
impl Drop for LayoutDocumentEquality{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"Layout document equality retains original descendant loans and funded frame storage")}}

